head.script:
scwin.onpageload = function() {
    var data1 = [];
    var row = 10;
    var col = 3;
    for (var i = 0; i < row; i++) {
        for (var j = 0; j < col; j++) {
            if (j === 0) {
                data1.push("LABEL=" + String(i));
            } else if (j === 1) {
                data1.push("VALUE=" + String(i));
            } else {
                data1.push("DUMMY=" + String(i));
            }
        }
    }
    dataList1.setData(data1);
};
scwin.onpageunload = function() {};
scwin.autoComplete1_onviewchange = function(info) {};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#autoComplete1_input', 'key-sequence', {
        sequence: 'label=4'
    });
}
scwin.setSimulate2 = function() {
    scwin.simulateWrapper('#autoComplete1_input', 'key-combo', {
        combo: 'ENTER'
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete1_label').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'autoComplete1_label').innerText == 'LABEL=4 VALUE=4'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
